      "description": "The year the Beta Cruiser was manufactured"
    },
    "length": {
      "type": "number",
      "description": "The length of the Beta Cruiser in meters"
    },
    "weapons": {
      "type": "array",
      "items": {
        "type": "string",
        "description": "The type of weapon on the Beta Cruiser"
      },
      "minItems": 1,
      "description": "An array of weapons on the Beta Cruiser"
    }
